#!/usr/bin/env python3
"""One-click installer for local-first song choices on PermBot's linked main music cog.

Run from the bot folder with: python patch.py
A timestamped backup is made before the source file is changed.
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
import sys
import tempfile
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PATCH_FILES = json.loads(base64.b64decode("").decode("utf-8"))
BASE_SHA256 = {"cogs/music.py": "144fedbb70c49e9dbeab8e4c76c86c1b8d1a189c3871adaceb5530c9c5caf2bc"}
BACKUP_ROOT = ROOT / ".backups"


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(target: Path, data: bytes) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary_name = tempfile.mkstemp(prefix=f".{target.name}.", suffix=".tmp", dir=target.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)


def main() -> int:
    target = (ROOT / "cogs/music.py").resolve()
    if not target.is_relative_to(ROOT.resolve()) or not target.is_file():
        print("ERROR: Run patch.py from the root of the PermBot folder; cogs/music.py was not found.", file=sys.stderr)
        return 1

    new_content = PATCH_FILES["cogs/music.py"].encode("utf-8")
    current = target.read_bytes()
    current_digest = digest(current)
    if current_digest == digest(new_content):
        print("[ALREADY INSTALLED] cogs/music.py")
        return 0
    if current_digest != BASE_SHA256["cogs/music.py"]:
        print(
            "ERROR: cogs/music.py does not match the linked PermBot main version (aba63f9). "
            "No files were changed. Update that file from GitHub or apply the patch manually.",
            file=sys.stderr,
        )
        return 1

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup = BACKUP_ROOT / f"song_choice_patch_{stamp}" / "cogs" / "music.py"
    backup.parent.mkdir(parents=True, exist_ok=False)
    backup.write_bytes(current)
    try:
        atomic_write(target, new_content)
    except Exception as error:
        try:
            atomic_write(target, current)
        except OSError as rollback_error:
            print(f"ERROR: Install failed ({error}); restore the backup at {backup}: {rollback_error}", file=sys.stderr)
            return 1
        print(f"ERROR: Install failed; original file restored: {error}", file=sys.stderr)
        return 1

    print("[UPDATED] cogs/music.py — local matches are shown first; YouTube/SoundCloud are fallback choices.")
    print(f"Backup: {backup.relative_to(ROOT)}")
    print("Install complete.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
